CREATE OR ALTER PROCEDURE [dbo].[uspGoodsReceipt_GetAll] (
	@SearchText NVARCHAR(MAX) = NULL
	, @PurchaseOrderId UNIQUEIDENTIFIER = NULL
	, @SupplierId UNIQUEIDENTIFIER = NULL
	, @WarehouseId UNIQUEIDENTIFIER = NULL
	, @Status NVARCHAR(MAX) = NULL
	, @ReceiptNumber NVARCHAR(MAX) = NULL
	, @ReceiptDate DATETIME = NULL
	, @Note NVARCHAR(MAX) = NULL
	, @Page INT = 1
	, @PageSize INT = 10
	, @SortField NVARCHAR(100) = NULL
	, @SortOrder NVARCHAR(20) = NULL)
AS
BEGIN
	SET NOCOUNT ON;
	IF @Page IS NULL OR @Page < 1 SET @Page = 1;
	IF @PageSize IS NULL OR @PageSize < 1 SET @PageSize = 10;
	IF @PageSize > 1000 SET @PageSize = 1000;

	;WITH TempResult AS
	(
		SELECT
			t.[Id]
			, t.[PurchaseOrderId]
			, t.[SupplierId]
			, t.[WarehouseId]
			, t.[ReceiptDate]
			, t.[Status]
			, t.[Note]
			, t.[ReceiptNumber]
			, t.[CreatedDate]
		FROM [dbo].[GoodsReceipt] AS t
		
		WHERE (ISNULL(@SearchText, '') = '' OR t.[ReceiptNumber] LIKE CONCAT('%', @SearchText, '%'))
			AND (@PurchaseOrderId IS NULL OR t.[PurchaseOrderId] = @PurchaseOrderId)
			AND (@SupplierId IS NULL OR t.[SupplierId] = @SupplierId)
			AND (@WarehouseId IS NULL OR t.[WarehouseId] = @WarehouseId)
			AND (ISNULL(@Status, '') = '' OR t.[Status] = @Status)
			AND (ISNULL(@ReceiptNumber, '') = '' OR t.[ReceiptNumber] LIKE CONCAT('%', @ReceiptNumber, '%'))
			AND (@ReceiptDate IS NULL OR t.[ReceiptDate] = @ReceiptDate)
			AND (ISNULL(@Note, '') = '' OR t.[Note] LIKE CONCAT('%', @Note, '%'))
			AND t.IsDeleted = 0
	),
	TempCount (TotalRow) AS (SELECT COUNT(*) FROM TempResult)
	SELECT r.*, c.TotalRow
	FROM TempResult AS r CROSS JOIN TempCount AS c
	ORDER BY
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'purchaseOrderId' THEN r.[PurchaseOrderId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'purchaseOrderId' THEN r.[PurchaseOrderId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'supplierId' THEN r.[SupplierId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'supplierId' THEN r.[SupplierId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'warehouseId' THEN r.[WarehouseId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'warehouseId' THEN r.[WarehouseId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'receiptDate' THEN r.[ReceiptDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'receiptDate' THEN r.[ReceiptDate] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'status' THEN r.[Status] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'status' THEN r.[Status] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'note' THEN r.[Note] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'note' THEN r.[Note] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'receiptNumber' THEN r.[ReceiptNumber] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'receiptNumber' THEN r.[ReceiptNumber] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END DESC,
		r.[CreatedDate] DESC
	OFFSET (@PageSize * (@Page - 1)) ROWS FETCH NEXT @PageSize ROWS ONLY
	OPTION (RECOMPILE);
END
